#include <stdlib.h>
#include <stdio.h>

struct resource_file {
  const char *path;
  unsigned char *bytes;
  size_t size;
};

static size_t resource_files_amount = 0;
static struct resource_file *resource_files = NULL;

static void resource_files_make(void);

struct resource_file *get_resource_files(size_t *amount) {
  if (resource_files == NULL) {
    resource_files_make();
  }

  if (amount != NULL) {    *amount = resource_files_amount;  }

  return resource_files;
}

static void resource_file_init(struct resource_file *resource_file, const char *path, size_t size) {
  resource_file->path = path;
  resource_file->bytes = (unsigned char *) malloc(size);
  resource_file->size = size;
}

static void resource_file_write(struct resource_file *resource_file, size_t *offset, size_t length, long data) {
  unsigned long v = (unsigned long)(unsigned long)data;

  // bounds check
  if (*offset + length > resource_file->size) {
    printf("Failed to write, out of bounds. Offset: %zu, Size: %zu\n", *offset, resource_file->size);
    exit(1);
  }

  for (size_t i = 0; i < length; i++) {
    resource_file->bytes[*offset + i] = (unsigned char)((v >> i * 8) &0xff);
  }

  *offset += sizeof(v);
}

